import releaseData from "../data/releaseHistory.json";
import type { FullHeroicon, HeroiconType, Iconset } from "../types";

// Release history of both iconsets, generated by scripts/release-history.mjs: which icons
// each release added, renamed or redrew. Used by the icon pages and the What's new page.

export type IconChange = {
  name: string;
  types: HeroiconType[];
  // Whether the change shows at the icon's size, or only in the SVG code
  visible: boolean;
  notes: string[];
  before: Partial<Record<HeroiconType, string>>;
};

export type ReleaseNote = { section: string | null; text: string; nested: boolean };

export type Release = {
  iconset: Iconset;
  version: string;
  date: string;
  url: string;
  // The iconset's first release (Heroicons: the first release of Heroicons 2)
  first: boolean;
  // Changelog lines under their section: Added, Changed, Fixed, Removed
  notes: ReleaseNote[];
  added: string[];
  removed: string[];
  renamed: { from: string; to: string }[];
  newStyles: Partial<Record<HeroiconType, string[]>>;
  changed: IconChange[];
};

export const releases = releaseData.releases as Release[];

export const sidekickiconReleases = releases.filter(
  (release) => release.iconset === "Sidekickicons",
);

// "2026-11-01" -> "1 November 2026", the same in every timezone
export function formatDate(date: string) {
  return new Date(date).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}

// Changelog lines that list the icons a release added, which pages show as icons instead
export const listsAddedIcons = (note: string) =>
  /^Add(ed)? (new|first|missing) icons/i.test(note);

type ReleaseInfo = Pick<Release, "iconset" | "version" | "date" | "url" | "first">;

export type HistoryEvent =
  | { kind: "added"; release: ReleaseInfo }
  | { kind: "renamed"; release: ReleaseInfo; from: string }
  | { kind: "newStyle"; release: ReleaseInfo; types: HeroiconType[] }
  | {
      kind: "changed";
      release: ReleaseInfo;
      types: HeroiconType[];
      notes: string[];
      // For visible changes: each changed style before and after the release
      drawings: { type: HeroiconType; before: string; after: string }[];
    };

const info = ({ iconset, version, date, url, first }: Release): ReleaseInfo => ({
  iconset,
  version,
  date,
  url,
  first,
});

// Everything that happened to an icon, oldest first
export function iconHistory(icon: FullHeroicon): HistoryEvent[] {
  // Oldest first, following renames back to the icon's earlier names
  const own = releases
    .filter((release) => release.iconset === icon.iconset)
    .toReversed();
  const names = new Set([icon.kebabName]);
  for (const release of own.toReversed())
    for (const { from, to } of release.renamed) if (names.has(to)) names.add(from);

  const events: HistoryEvent[] = [];
  for (const release of own) {
    // Only the first time: Heroicons 2.0.3 brought back a misspelled old name for a while
    const added = events.some((event) => event.kind === "added");
    if (!added && release.added.some((name) => names.has(name)))
      events.push({ kind: "added", release: info(release) });
    const rename = release.renamed.find(({ to }) => names.has(to));
    if (rename)
      events.push({ kind: "renamed", release: info(release), from: rename.from });
    const newStyles = (Object.keys(release.newStyles) as HeroiconType[]).filter(
      (type) => release.newStyles[type]!.some((name) => names.has(name)),
    );
    if (newStyles.length)
      events.push({ kind: "newStyle", release: info(release), types: newStyles });
    const change = release.changed.find(({ name }) => names.has(name));
    if (change)
      events.push({
        kind: "changed",
        release: info(release),
        types: change.types,
        notes: change.notes,
        drawings: [],
      });
  }

  // A redraw's "after" is the next redraw's "before", or the icon as it is now
  const changes = own.flatMap((release) =>
    release.changed.filter(({ name }) => names.has(name)),
  );
  const changedEvents = events.filter((event) => event.kind === "changed");
  changes.forEach((change, i) => {
    changedEvents[i].drawings = (Object.keys(change.before) as HeroiconType[]).map(
      (type) => ({
        type,
        before: change.before[type]!,
        after:
          changes.slice(i + 1).find((later) => later.before[type])?.before[type] ??
          icon[type],
      }),
    );
  });

  return events;
}

// A changelog line as text, code and links, for rendering without {@html}
export type NoteSegment =
  | { kind: "text"; text: string }
  | { kind: "code"; text: string }
  | { kind: "link"; text: string; href: string };

export function noteSegments(note: string): NoteSegment[] {
  const segments: NoteSegment[] = [];
  const pattern = /`([^`]+)`|\[([^\]]+)\]\(([^)]+)\)/g;
  let last = 0;
  for (const match of note.matchAll(pattern)) {
    if (match.index > last)
      segments.push({ kind: "text", text: note.slice(last, match.index) });
    if (match[1]) segments.push({ kind: "code", text: match[1] });
    else segments.push({ kind: "link", text: match[2], href: match[3] });
    last = match.index + match[0].length;
  }
  if (last < note.length) segments.push({ kind: "text", text: note.slice(last) });
  return segments;
}
